package com.example.domain.intelligence

import android.content.Context
import com.example.domain.permission.VybPermissionManager

/**
 * Action Plan Engine.
 * Manages multi-step Action Plans generated by agents.
 * Supports step-by-step sequential execution, pauses at confirmation gates,
 * and records verification proofs.
 */
class ActionPlanEngine {

    suspend fun executeNextStep(
        plan: ActionPlan,
        intent: UniversalIntent,
        agent: VybAgent,
        context: ResolvedPersonalContext,
        appContext: Context?,
        permissionManager: VybPermissionManager?
    ): ActionPlan {
        if (plan.status == PlanStatus.COMPLETED || plan.status == PlanStatus.FAILED || plan.status == PlanStatus.CANCELLED) {
            return plan
        }

        val stepIdx = plan.currentStepIndex
        if (stepIdx >= plan.steps.size) {
            return plan.copy(status = PlanStatus.COMPLETED)
        }

        val currentStep = plan.steps[stepIdx]

        // If step requires human confirmation and plan is not yet in progress, pause for confirmation
        if (currentStep.requiresConfirmation && plan.status == PlanStatus.DRAFT) {
            val updatedSteps = plan.steps.toMutableList()
            updatedSteps[stepIdx] = currentStep.copy(status = StepStatus.CONFIRMATION_REQUIRED)
            return plan.copy(
                steps = updatedSteps,
                status = PlanStatus.AWAITING_CONFIRMATION
            )
        }

        // Execute the step via the assigned agent
        val updatedSteps = plan.steps.toMutableList()
        updatedSteps[stepIdx] = currentStep.copy(status = StepStatus.RUNNING)

        val result = agent.executeStep(currentStep, intent, context, appContext, permissionManager)

        if (result.success) {
            updatedSteps[stepIdx] = currentStep.copy(
                status = StepStatus.COMPLETED,
                output = result.outputSummary,
                verification = result.verification
            )
            val nextIdx = stepIdx + 1
            val nextStatus = if (nextIdx >= plan.steps.size) PlanStatus.COMPLETED else PlanStatus.IN_PROGRESS
            return plan.copy(
                steps = updatedSteps,
                currentStepIndex = nextIdx,
                status = nextStatus
            )
        } else {
            updatedSteps[stepIdx] = currentStep.copy(
                status = StepStatus.FAILED,
                output = result.outputSummary,
                verification = result.verification
            )
            return plan.copy(
                steps = updatedSteps,
                status = PlanStatus.FAILED
            )
        }
    }

    suspend fun executeFullPlan(
        plan: ActionPlan,
        intent: UniversalIntent,
        agent: VybAgent,
        context: ResolvedPersonalContext,
        appContext: Context?,
        permissionManager: VybPermissionManager?
    ): ActionPlan {
        var current = plan.copy(status = PlanStatus.IN_PROGRESS)
        while (current.status == PlanStatus.IN_PROGRESS || current.status == PlanStatus.DRAFT) {
            val next = executeNextStep(current, intent, agent, context, appContext, permissionManager)
            if (next.status == PlanStatus.AWAITING_CONFIRMATION || next.status == PlanStatus.FAILED || next == current) {
                return next
            }
            current = next
        }
        return current
    }
}
